mapper.sql:
from 

    and (g.asset_cd ilike #{q.keywordLike} escape '\' or g.asset_nm ilike #{q.keywordLike} escape '\'
        or g.serial_no ilike #{q.keywordLike} escape '\')
    and g.gauge_class = #{q.gaugeClass}
    and g.status = #{q.status}
    and g.use_yn = 'Y'

mapper.select:
select 
  from qms_gauge_calib c left join mst_cust u on u.cust_id = c.cust_id
 where c.calib_id = #{calibId}

mapper.update:
update mst_phys_asset set gauge_class = #{gaugeClass}, calib_cycle_days = #{cycleDays},
                          row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asset_id = #{assetId} and asset_type = 'GAUGE' and row_ver = #{rowVer}
